# ---- companies extension lessons (c23-c31) ----
L.append(dict(id='c23-prefix-fenwick',title='Prefix Sums & Fenwick Trees',used=['p70-subarray-sum-k','p75-range-sum-fenwick','p74-snapshot-array'],scenes=[
 S('title',['Prefix sums and Fenwick trees answer one question very fast: what is the total between position l and position r?'],title='Prefix Sums & Fenwick Trees',sub='range totals in O(1) or O(log n)'),
 S('analogy',['Think of a car odometer.','To know how far you drove between Tuesday and Friday, you do not re-drive the road.','You read the odometer on Friday and subtract the reading from Tuesday.','A prefix sum array is an odometer for an array: each cell stores the running total so far.'],title='The odometer trick',text='Distance from Tuesday to Friday = odometer(Friday) − odometer(Tuesday). Prefix sums store the running total, so any range total is one subtraction.',icons=['Tue: 120 km','Fri: 410 km','driven: 290 km']),
 S('array',['Here is an array and its prefix array.','P of i is the sum of the first i numbers, with P of zero equal to zero.','The sum from index one to index three is P of four minus P of one.','That is twelve minus three, which is nine, computed with one subtraction.'],title='P[i] = a[0] + … + a[i−1]',states=[dict(a=[3,1,4,4,2],note='a'),dict(a=[0,3,4,8,12,14],note='P (one longer, P[0] = 0)'),dict(a=[0,3,4,8,12,14],ptr={'l':1,'r+1':4},hl=[1,4],note='sum a[1..3] = P[4] − P[1] = 12 − 3 = 9')]),
 S('hash',['Prefix sums plus a hash map count subarrays that add up to k.','As we walk, we keep a map from each prefix total to how many times we saw it.','If the current total minus k was seen before, every earlier spot with that total starts a subarray summing to k.','This turns an n squared search into one pass.'],title='Subarray sum = k (k = 7)',buckets=4,states=[dict(table=[['0×1'],[],[],[]],note='seen {0:1}'),dict(key=7,b=0,calc='prefix 7 − k = 0 → seen once',table=[['0×1'],['3×1'],['4×1'],['7×1']],note='count += 1'),dict(key=14,b=3,calc='prefix 14 − k = 7 → seen once',table=[['0×1'],['3×1'],['4×1'],['7×1','14×1']],note='count += 1')]),
 S('bullets',['But plain prefix sums break when values change: one update forces you to rewrite every later total.','A Fenwick tree, also called a binary indexed tree, fixes this.','Each cell stores the sum of a block whose length is the lowest set bit of its index.','Update and query both walk about log n cells, by adding or removing that lowest bit.'],title='Fenwick tree in plain words',items=['cell i covers (i − lowbit(i), i]','lowbit(i) = i & −i','query: i −= lowbit(i) → O(log n)','update: i += lowbit(i) → O(log n)']),
 S('array',['Here is a query for the first seven numbers.','Seven is binary one one one. Cell seven covers one number.','Drop the lowest bit to get six, which covers two numbers.','Drop again to get four, which covers four numbers. Three cells, and we are done.'],title='prefix(7) walks 7 → 6 → 4',states=[dict(a=[0,3,4,4,12,2,2,5],ptr={'i':7},hl=[7],note='tree[7] covers a[7]'),dict(a=[0,3,4,4,12,2,2,5],ptr={'i':6},hl=[7,6],note='tree[6] covers a[5..6]'),dict(a=[0,3,4,4,12,2,2,5],ptr={'i':4},hl=[7,6,4],note='tree[4] covers a[1..4] → sum = 5 + 2 + 12 = 19')]),
 S('title',['Static data: use a prefix array. Changing data: use a Fenwick tree. Ranges of any shape: say segment tree as the follow up.'],title='Recap',sub='odometer • prefix + hash map • Fenwick lowbit walk'),
]))
L.append(dict(id='c24-monotonic-stack',title='Monotonic Stacks',used=['p05-daily-temperatures','p25-trapping-rain-water','p79-maximal-square'],scenes=[
 S('title',['A monotonic stack finds, for every item, the next item that is bigger or smaller, in one pass.'],title='Monotonic Stacks',sub='next greater element in O(n)'),
 S('analogy',['Picture people standing in a line at a parade, looking right.','Short people behind a tall person can never be seen past that tall person.','So when a tall person arrives, every shorter person waiting has found their answer, and they leave.','The waiting people always stand from tallest to shortest. That is the monotonic stack.'],title='The parade line',text='When someone taller arrives, everyone shorter who is waiting has found their "next taller" and leaves. Those still waiting are always sorted tallest to shortest.',icons=['🧍','🧍‍♂️','🧍‍♀️']),
 S('stack',['Daily temperatures: how many days until a warmer day?','We push day indexes. The stack keeps temperatures decreasing from bottom to top.','When seventy five arrives, it is warmer than seventy one and seventy three, so both pop and get their answers.','Each day is pushed once and popped once, so the whole thing is linear.'],title='Daily temperatures: 73 74 75 71 69 72 76',states=[dict(items=['74'],note='73 popped by 74 (answer 1)'),dict(items=['75'],note='74 popped by 75'),dict(items=['75','71','69'],note='decreasing: still waiting'),dict(items=['75','72'],note='72 pops 69 and 71'),dict(items=['76'],note='76 pops 72 and 75')]),
 S('bullets',['How to choose the direction.','Want next greater? Keep the stack decreasing, and pop while the new item is bigger.','Want next smaller? Keep it increasing, and pop while the new item is smaller.','Store indexes, not values, so you can compute distances and widths.'],title='Which way?',items=['next greater → decreasing stack','next smaller → increasing stack','store indexes','each item pushed + popped once → O(n)']),
 S('bullets',['Where it shows up in interviews.','Largest rectangle in a histogram and maximal rectangle in a matrix.','Trapping rain water, where a pop finds a basin between two walls.','Stock span and removing digits to make the smallest number.'],title='Interview uses',items=['largest rectangle / maximal rectangle','trapping rain water','stock span','remove k digits']),
 S('title',['Keep a stack sorted, pop when the new item breaks the order, and the popped item has found its answer.'],title='Recap',sub='parade line • pop = answer found • O(n)'),
]))
L.append(dict(id='c25-topological-sort',title='Topological Sort (Kahn\'s Algorithm)',used=['p11-course-schedule','p33-alien-dictionary'],scenes=[
 S('title',['Topological sort puts tasks in an order where every task comes after the tasks it depends on.'],title='Topological Sort',sub='dependencies first, then the rest'),
 S('analogy',['Think about getting dressed.','Socks before shoes, underwear before trousers, shirt before tie.','Any order that respects all of these arrows is fine.','If the rules were shoes before socks and socks before shoes, there would be no valid order. That is a cycle.'],title='Getting dressed',text='Socks → shoes, shirt → tie, trousers → belt. Any order that respects the arrows works. A cycle (socks → shoes → socks) means no valid order exists.',icons=['🧦→👟','👔→🎀','cycle = impossible']),
 S('graph',['Kahn\'s algorithm counts incoming arrows for each node. That count is the in degree.','Every node with in degree zero is ready, so put it in a queue.','Take one out, add it to the order, and remove its outgoing arrows.','Any neighbor whose count drops to zero becomes ready.'],title='Kahn: peel off nodes with in-degree 0',directed=True,nodes=[['A',120,140],['B',120,300],['C',330,220],['D',540,140],['E',540,300]],edges=[[0,2],[1,2],[2,3],[2,4],[0,3]],states=[dict(hl=[0,1],side={'queue':'[A, B]','order':'[]'},note='A, B have in-degree 0'),dict(ok=[0,1],hl=[2],side={'queue':'[C]','order':'[A, B]'},note='C drops to 0'),dict(ok=[0,1,2],hl=[3,4],side={'queue':'[D, E]','order':'[A, B, C]'}),dict(ok=[0,1,2,3,4],side={'order':'[A, B, C, D, E]'},note='all 5 output → no cycle')]),
 S('bullets',['How to detect a cycle.','If the output order has fewer nodes than the graph, some nodes never reached zero.','Those nodes are stuck in a cycle.','This is exactly the course schedule problem: can you finish all courses?'],title='Cycle check',items=['output size < n → cycle','cost O(V + E)','DFS version: three colors, gray = on path','course schedule, build systems, driver probe order']),
 S('title',['Count in degrees, start from zeros, peel layer by layer. Fewer outputs than nodes means a cycle.'],title='Recap',sub='getting dressed • in-degree queue • cycle check'),
]))
L.append(dict(id='c26-grid-dp',title='Grid Dynamic Programming',used=['p79-maximal-square','p42-edit-distance'],scenes=[
 S('title',['Grid dynamic programming fills a table cell by cell, where each cell only looks at neighbors already filled in.'],title='Grid DP',sub='each cell from up, left and diagonal'),
 S('analogy',['Picture a city with streets in a grid, and you may only walk right or down.','How many ways reach a corner? Exactly the ways to reach the corner above plus the ways to reach the corner to the left.','You never recount a route: you write the number on each corner and reuse it.','That written number is the D P table.'],title='Walking city blocks',text='Ways to reach a corner = ways from above + ways from the left. Write each answer on the corner so you never recount.',icons=['→','↓','memo on each corner']),
 S('grid',['Here is the unique paths table for a three by four grid.','The top row and left column have only one way each.','Every other cell is up plus left.','The bottom right corner holds ten, the number of routes.'],title='Unique paths: dp = up + left',colLabels=['0','1','2','3'],rowLabels=['0','1','2'],states=[dict(g=[[1,1,1,1],[1,'·','·','·'],[1,'·','·','·']],note='edges: 1 way'),dict(g=[[1,1,1,1],[1,2,3,4],[1,'·','·','·']],hl=[[1,1],[1,2],[1,3]],note='row 1'),dict(g=[[1,1,1,1],[1,2,3,4],[1,3,6,10]],ok=[[2,3]],note='answer 10')]),
 S('grid',['Maximal square uses the same idea with a minimum.','A cell can be the bottom right corner of a square of side k only if its up, left and diagonal neighbors all allow side k minus one.','So dp equals one plus the minimum of those three.','The biggest value in the table is the side of the biggest square of ones.'],title='Maximal square: 1 + min(up, left, diag)',colLabels=['0','1','2','3'],rowLabels=['0','1','2'],states=[dict(g=[[1,0,1,1],[1,1,1,1],[0,1,1,1]],note='input'),dict(g=[[1,0,1,1],[1,1,1,2],[0,1,2,'·']],hl=[[1,3],[2,2]],note='dp so far'),dict(g=[[1,0,1,1],[1,1,1,2],[0,1,2,2]],ok=[[2,3]],note='max side = 2 → area 4')]),
 S('bullets',['A memory trick interviewers like.','Each row only needs the row above, so keep one row and a saved diagonal.','Memory drops from rows times columns to just columns.','Always say the recurrence, the base cases and the fill order before coding.'],title='Say it like this',items=['state: dp[r][c] means …','recurrence from up / left / diag','base: first row & column','space: keep one row → O(cols)']),
 S('title',['Define the cell, write the recurrence from finished neighbors, fill row by row, and shrink to one row if asked.'],title='Recap',sub='city blocks • up + left • 1 + min'),
]))
L.append(dict(id='c27-string-matching',title='String Matching: KMP & Rolling Hash',used=['p02-longest-substring','p77-longest-palindrome-substring'],scenes=[
 S('title',['How do you find a pattern inside a long text without starting over after every mismatch?'],title='KMP & Rolling Hash',sub='pattern search in O(n + m)'),
 S('analogy',['Imagine reading a song lyric and humming along.','If you sang la la la and then made a mistake, you do not restart the whole song.','You remember that the last la la is still the start of the chorus, and continue from there.','KMP remembers that overlap in a small table called the failure function.'],title='Humming along',text='After a mistake you keep the part you already matched that is also the start of the pattern. KMP stores that overlap so it never re-reads text.',icons=['🎵 la la la','✗','continue from "la la"']),
 S('array',['Here is the failure table for the pattern A B A B C.','Each entry is the length of the longest proper prefix that is also a suffix of the pattern up to that point.','At index three, A B A B ends with A B, which is also its start, so the value is two.','On a mismatch, jump the pattern pointer to that value instead of zero.'],title='Failure table for "ABABC"',states=[dict(a=['A','B','A','B','C'],note='pattern'),dict(a=[0,0,1,2,0],ptr={'j':3},hl=[3],note='"ABAB" → border "AB" = 2'),dict(a=[0,0,1,2,0],ptr={'j':2},hl=[2],note='mismatch at C → resume j = 2')]),
 S('bullets',['Rolling hash, used by Rabin Karp, is the other classic.','Turn each window into a number, like reading digits.','Sliding by one removes the leftmost digit and adds a new one, in constant time.','If hashes match, compare characters to rule out a rare collision.'],title='Rolling hash',items=['hash = c0·B^(m−1) + … + c(m−1)','slide: remove left, ×B, add right','mod a large prime','verify on match (collisions)']),
 S('title',['KMP never re-reads text thanks to the failure table; rolling hash compares windows as numbers. Both run in linear time.'],title='Recap',sub='humming along • failure table • rolling hash'),
]))
L.append(dict(id='c28-idempotency-retries',title='Idempotency & Safe Retries',used=['p103-retry-client-idempotency','p84-logger-rate-limiter'],scenes=[
 S('title',['Networks fail in the middle of requests. Idempotency makes it safe to try again.'],title='Idempotency & Retries',sub='retry without double-charging'),
 S('analogy',['Think about an elevator call button.','Pressing it five times does not call five elevators. The result of one press and five presses is the same.','A payment API should behave like that button.','The client attaches an idempotency key, a unique ticket number, and the server remembers the result for that ticket.'],title='The elevator button',text='Pressing the button once or five times gives the same result. An idempotency key makes a payment request behave the same way.',icons=['🔘 ×5','🛗 ×1','ticket = idempotency key']),
 S('flow',['Here is the dangerous case.','The client sends charge, with key k1. The server charges the card.','The reply is lost on the way back, so the client times out and retries with the same key.','The server sees k1 already done and returns the saved result. No second charge.'],title='Lost reply, safe retry',nodes=[['client',110,200],['API',350,200],['key store',600,110],['ledger',600,290]],edges=[[0,1],[1,2],[1,3]],states=[dict(hl=[0],dot=[0,1],note='POST /charge key=k1'),dict(hl=[3],dot=[1,3],note='charge recorded, reply lost'),dict(hl=[0],dot=[0,1],note='timeout → retry, same key k1'),dict(hl=[2],dot=[1,2],note='k1 found → return saved result')]),
 S('bullets',['Retry rules that interviewers check.','Reuse the same key for every retry of one logical request. A new key means a new charge.','Retry only on timeouts, connection errors, too many requests and five hundred errors, never on four hundred errors like bad input.','Back off exponentially with jitter, and cap the attempts.'],title='Retry checklist',items=['same key for all retries','retry 429 / 5xx / timeouts only','exponential backoff + jitter','cap attempts; honor Retry-After']),
 S('title',['Make writes idempotent with a key, retry only safe failures, and back off with jitter.'],title='Recap',sub='elevator button • same key • backoff + jitter'),
]))
L.append(dict(id='c29-cdn-edge',title='CDNs & Edge Caching',used=['p107-cache-simulator','p20-lru-cache'],scenes=[
 S('title',['A content delivery network keeps copies of popular files close to the people who watch them.'],title='CDNs & Edge Caching',sub='bring bytes closer to users'),
 S('analogy',['Think of a bakery chain.','Baking everything in one central factory means long delivery trips.','So each neighborhood shop keeps the most popular bread on its shelves, and only orders from the factory when it runs out.','The shops are edge caches, and the factory is the origin.'],title='Neighborhood bakeries',text='Popular bread sits on local shelves (edge). Only misses go back to the factory (origin). Most customers never wait for a truck.',icons=['🏭 origin','🏪 edge','🍞 popular items']),
 S('flow',['Here is a request path.','A viewer asks the nearest edge for a video chunk.','On a hit the edge answers immediately.','On a miss it asks a regional shield cache, and only then the origin, then keeps a copy.'],title='Edge → shield → origin',nodes=[['viewer',100,200],['edge',320,200],['shield',540,200],['origin',760,200]],edges=[[0,1],[1,2],[2,3]],states=[dict(hl=[1],dot=[0,1],note='hit: answered in a few ms'),dict(hl=[2],dot=[1,2],note='miss → regional shield'),dict(hl=[3],dot=[2,3],note='shield miss → origin'),dict(hl=[1],note='copies cached on the way back')]),
 S('bullets',['Words to use in a design interview.','Hit ratio, the share of requests served from cache, drives cost and latency.','Time to live and versioned file names decide freshness.','Netflix pre-positions popular titles on its Open Connect appliances overnight, before people press play.'],title='Design vocabulary',items=['hit ratio → cost + latency','TTL / versioned URLs / purge','origin shield collapses misses','pre-positioning (Netflix Open Connect)']),
 S('title',['Cache popular content at the edge, shield the origin, and plan freshness with TTLs and versioned names.'],title='Recap',sub='bakeries • edge / shield / origin • hit ratio'),
]))
L.append(dict(id='c30-transactions-mvcc',title='Transactions, MVCC & Write-Ahead Logs',used=['p101-inmem-db-transactions','p94-clock-buffer-pool','p97-time-kv-store'],scenes=[
 S('title',['A transaction groups changes so they all happen or none happen, even if the machine crashes halfway.'],title='Transactions, MVCC & WAL',sub='all or nothing, readers never blocked'),
 S('analogy',['Think of moving money between two jars at home.','You first write in a notebook: move ten dollars from jar A to jar B.','Then you move the money. If you are interrupted, the notebook tells you exactly what to finish or undo.','That notebook is the write ahead log, written before the real change.'],title='The household notebook',text='Write the plan in the notebook first, then move the money. After an interruption the notebook says what to redo or undo.',icons=['📓 log first','🫙 A → 🫙 B','crash → replay notebook']),
 S('bullets',['A C I D in plain words.','Atomic: all or nothing.','Consistent: rules like balances never going negative still hold.','Isolated: concurrent transactions do not see each other\'s half finished work.','Durable: once committed, it survives a crash, because the log was flushed to disk first.'],title='ACID',items=['Atomic: all or nothing','Consistent: invariants hold','Isolated: no half-done reads','Durable: log flushed before "OK"']),
 S('array',['Multi version concurrency control keeps several versions of each row.','A writer adds a new version with its transaction time instead of overwriting.','A reader that started at time five keeps seeing the version from time three.','So readers never block writers, and old versions are cleaned up later.'],title='MVCC: versions of key x',states=[dict(a=['t1:10','t3:20'],note='versions of x'),dict(a=['t1:10','t3:20','t7:30'],hl=[2],note='writer at t7 appends'),dict(a=['t1:10','t3:20','t7:30'],ptr={'reader@t5':1},ok=[1],note='snapshot at t5 sees 20')]),
 S('bullets',['How nested transactions work in the practical interview store.','Begin pushes an undo log.','Each set records the old value in the top undo log.','Rollback replays it in reverse; commit merges it into the parent, or discards it at the top level.'],title='Undo logs in code',items=['BEGIN → push undo map','SET → save old value once','ROLLBACK → restore, pop','COMMIT → merge into parent']),
 S('title',['Log first, then change. Keep versions so readers see a stable snapshot. Undo logs make rollback simple.'],title='Recap',sub='notebook • ACID • MVCC snapshot'),
]))
L.append(dict(id='c31-leader-election',title='Leader Election & Leases',used=['d02-hash-ring','p100-inmem-db-levels'],scenes=[
 S('title',['Many systems need exactly one node in charge. Leader election picks it, and leases make sure an old leader steps down.'],title='Leader Election & Leases',sub='one boss at a time'),
 S('analogy',['Think of a group project where one person holds the only marker for the whiteboard.','Whoever holds the marker writes; everyone else reads.','If that person leaves the room for too long, the group votes and gives a new marker to someone else.','The old person must know their marker has expired, or two people would write over each other.'],title='The whiteboard marker',text='One marker, one writer. If the holder disappears past the timeout, the group votes a new holder, and the old marker stops working.',icons=['🖊️ one writer','⏱️ timeout','🗳️ majority vote']),
 S('flow',['Here is a Raft style election.','The leader sends heartbeats. Followers reset their timers.','The leader crashes, heartbeats stop, and one follower\'s random timer fires first.','It becomes a candidate for term two, asks for votes, and wins with a majority of three.'],title='Election by majority',nodes=[['A (leader)',130,200],['C',380,200],['B',640,90],['D',640,200],['E',640,320]],edges=[[0,1],[1,2],[1,3],[1,4]],states=[dict(hl=[0],dot=[0,1],note='term 1: A sends heartbeats'),dict(bad=[0],note='A crashes → heartbeats stop'),dict(hl=[1],dot=[1,3],note='C times out first → candidate, term 2, asks votes'),dict(hl=[1,2,3],note='C gets votes from B and D → 3 of 5 → leader')]),
 S('bullets',['Avoiding two leaders, called split brain.','Require a majority, so two groups can never both win.','Use a term or epoch number, a fencing token, and reject writes from older terms.','Leases give the leader a time limited right to act; it must stop before the lease ends.'],title='No split brain',items=['majority quorum','term / epoch numbers','fencing tokens on storage','leases with clock margin']),
 S('title',['Majority votes pick one leader, terms and fencing tokens reject old leaders, and leases bound how long anyone can act alone.'],title='Recap',sub='marker • majority • fencing'),
]))
